/** Shared studio-FX DSP primitives.
 *
 *  Line-for-line port of `shared/audio-fx/ts/primitives.ts` (itself a port of
 *  `StudioDsp.kt`). Every intermediate stays in `float`: on all supported
 *  targets float arithmetic rounds per operation exactly like the JVM/JS
 *  `f()` funnel, so recursive filters cannot drift from the phone/desktop
 *  renders. `test_studiofx_parity.cpp` locks the result to the golden vectors
 *  generated by the Kotlin engine.
 */
inline float dbToLinear (float db) noexcept
{
    return static_cast<float> (std::pow (10.0, static_cast<double> (db) / 20.0));
}

inline float levelToDb (float linear) noexcept
{
    return linear <= 1e-6f ? -120.0f
                           : static_cast<float> (20.0 * std::log10 (static_cast<double> (linear)));
}

/** One-pole parameter smoother so slider moves never step the audio. */
class SmoothValue
{
public:
    SmoothValue (float initial, float sampleRate, float timeConstantMs) noexcept
        : current (initial)
        , target (initial)
        , running (false)
        , coeff (timeConstantMs <= 0.0f
                     ? 0.0f
                     : static_cast<float> (std::exp (-1.0 / ((static_cast<double> (timeConstantMs) * sampleRate) / 1000.0))))
    {
    }

    void set (float value) noexcept
    {
        if (running)
            target = value;
        else
            current = target = value;
    }

    void snap (float value) noexcept
    {
        current = value;
        target = value;
        running = true;
    }

    float next() noexcept
    {
        running = true;
        current = target + coeff * (current - target);
        return current;
    }

private:
    float current, target;
    bool running;
    float coeff;
};

/** Direct-form-II transposed biquad with independent mono state. */
class Biquad
{
public:
    Biquad() noexcept
        : fs (48000.0f)
    {
        setBypass();
    }

    explicit Biquad (float sampleRate) noexcept
        : fs (sampleRate)
    {
    }

    float process (float x) noexcept
    {
        const float y = b0 * x + z1;
        z1 = b1 * x - a1 * y + z2;
        z2 = b2 * x - a2 * y;
        // Match the shared engines: recover from a non-finite sample and flush
        // denormals instead of carrying poisoned state for the session.
        if (! std::isfinite (y))
        {
            reset();
            return 0.0f;
        }
        if (std::fabs (y) < 1e-30f)
        {
            z1 = z2 = 0.0f;
            return 0.0f;
        }
        return y;
    }

    void reset() noexcept { z1 = z2 = 0.0f; }

    void setBypass() noexcept
    {
        b0 = 1.0f;
        b1 = b2 = a1 = a2 = 0.0f;
    }

    void setLowShelf (float freq, float gainDb, float slope = 1.0f) noexcept
    {
        const float fr = std::min (std::max (freq, 10.0f), fs * 0.45f);
        const double a = std::pow (10.0, gainDb / 40.0);
        const double w0 = (2.0 * kPi * fr) / fs;
        const double cw = std::cos (w0), sw = std::sin (w0);
        const double alpha = (sw / 2.0) * std::sqrt ((a + 1.0 / a) * (1.0 / slope - 1.0) + 2.0);
        const double twoSqrtAAlpha = 2.0 * std::sqrt (a) * alpha;
        const double a0 = a + 1.0 + (a - 1.0) * cw + twoSqrtAAlpha;
        b0 = static_cast<float> ((a * (a + 1.0 - (a - 1.0) * cw + twoSqrtAAlpha)) / a0);
        b1 = static_cast<float> ((2.0 * a * (a - 1.0 - (a + 1.0) * cw)) / a0);
        b2 = static_cast<float> ((a * (a + 1.0 - (a - 1.0) * cw - twoSqrtAAlpha)) / a0);
        a1 = static_cast<float> ((-2.0 * (a - 1.0 + (a + 1.0) * cw)) / a0);
        a2 = static_cast<float> ((a + 1.0 + (a - 1.0) * cw - twoSqrtAAlpha) / a0);
    }

    void setHighShelf (float freq, float gainDb, float slope = 1.0f) noexcept
    {
        const float fr = std::min (std::max (freq, 10.0f), fs * 0.45f);
        const double a = std::pow (10.0, gainDb / 40.0);
        const double w0 = (2.0 * kPi * fr) / fs;
        const double cw = std::cos (w0), sw = std::sin (w0);
        const double alpha = (sw / 2.0) * std::sqrt ((a + 1.0 / a) * (1.0 / slope - 1.0) + 2.0);
        const double twoSqrtAAlpha = 2.0 * std::sqrt (a) * alpha;
        const double a0 = a + 1.0 - (a - 1.0) * cw + twoSqrtAAlpha;
        b0 = static_cast<float> ((a * (a + 1.0 + (a - 1.0) * cw + twoSqrtAAlpha)) / a0);
        b1 = static_cast<float> ((-2.0 * a * (a - 1.0 + (a + 1.0) * cw)) / a0);
        b2 = static_cast<float> ((a * (a + 1.0 + (a - 1.0) * cw - twoSqrtAAlpha)) / a0);
        a1 = static_cast<float> ((2.0 * (a - 1.0 - (a + 1.0) * cw)) / a0);
        a2 = static_cast<float> ((a + 1.0 - (a - 1.0) * cw - twoSqrtAAlpha) / a0);
    }

    void setPeaking (float freq, float gainDb, float q) noexcept
    {
        const float fr = std::min (std::max (freq, 10.0f), fs * 0.45f);
        const double a = std::pow (10.0, gainDb / 40.0);
        const double w0 = (2.0 * kPi * fr) / fs;
        const double cw = std::cos (w0), sw = std::sin (w0);
        const double alpha = sw / (2.0 * std::max (q, 0.05f));
        const double a0 = 1.0 + alpha / a;
        b0 = static_cast<float> ((1.0 + alpha * a) / a0);
        b1 = static_cast<float> ((-2.0 * cw) / a0);
        b2 = static_cast<float> ((1.0 - alpha * a) / a0);
        a1 = static_cast<float> ((-2.0 * cw) / a0);
        a2 = static_cast<float> ((1.0 - alpha / a) / a0);
    }

    /** First-order high pass, the real pole of the 3rd-order console HPF. */
    void setFirstOrderHighPass (float freq) noexcept
    {
        const float fr = std::min (std::max (freq, 5.0f), fs * 0.45f);
        const float k = static_cast<float> (std::tan ((kPi * fr) / fs));
        const float norm = 1.0f / (1.0f + k);
        b0 = norm;
        b1 = -norm;
        b2 = 0.0f;
        a1 = (k - 1.0f) * norm;
        a2 = 0.0f;
    }

    void setHighPass (float freq, float q) noexcept
    {
        const float fr = std::min (std::max (freq, 5.0f), fs * 0.45f);
        const double w0 = (2.0 * kPi * fr) / fs;
        const double cw = std::cos (w0), sw = std::sin (w0);
        const double alpha = sw / (2.0 * std::max (q, 0.05f));
        const double a0 = 1.0 + alpha;
        b0 = static_cast<float> ((1.0 + cw) / 2.0 / a0);
        b1 = static_cast<float> (-(1.0 + cw) / a0);
        b2 = static_cast<float> ((1.0 + cw) / 2.0 / a0);
        a1 = static_cast<float> ((-2.0 * cw) / a0);
        a2 = static_cast<float> ((1.0 - alpha) / a0);
    }

    void setLowPass (float freq, float q) noexcept
    {
        const float fr = std::min (std::max (freq, 10.0f), fs * 0.45f);
        const double w0 = (2.0 * kPi * fr) / fs;
        const double cw = std::cos (w0), sw = std::sin (w0);
        const double alpha = sw / (2.0 * std::max (q, 0.05f));
        const double a0 = 1.0 + alpha;
        b0 = static_cast<float> ((1.0 - cw) / 2.0 / a0);
        b1 = static_cast<float> ((1.0 - cw) / a0);
        b2 = static_cast<float> ((1.0 - cw) / 2.0 / a0);
        a1 = static_cast<float> ((-2.0 * cw) / a0);
        a2 = static_cast<float> ((1.0 - alpha) / a0);
    }

private:
    static constexpr double kPi = 3.141592653589793;
    float fs;
    float b0 = 1.0f, b1 = 0.0f, b2 = 0.0f, a1 = 0.0f, a2 = 0.0f;
    float z1 = 0.0f, z2 = 0.0f;
};

/** Cascade of biquads for steeper slopes. */
class BiquadCascade
{
public:
    BiquadCascade (float sampleRate, std::size_t stages)
        : filters (stages, Biquad (sampleRate))
    {
    }

    float process (float x) noexcept
    {
        for (auto& filter : filters)
            x = filter.process (x);
        return x;
    }

    void reset() noexcept
    {
        for (auto& filter : filters)
            filter.reset();
    }

    void bypass() noexcept
    {
        for (auto& filter : filters)
            filter.setBypass();
    }

    void setButterworthLowPass (float freq) noexcept
    {
        static constexpr float qs2[2] = { 0.5412f, 1.3066f };
        static constexpr float qs3[3] = { 0.5412f, 1.3066f, 0.7071f };
        for (std::size_t i = 0; i < filters.size(); ++i)
        {
            if (filters.size() == 1)
                filters[i].setLowPass (freq, 0.7071f);
            else if (filters.size() == 2)
                filters[i].setLowPass (freq, i < 2 ? qs2[i] : 0.7071f);
            else if (i < 3)
                filters[i].setLowPass (freq, qs3[i]);
            else
                filters[i].setBypass();
        }
    }

    void setThirdOrderHighPass (float freq) noexcept
    {
        // Butterworth 3rd order: one real pole plus one complex pair at Q = 1.
        if (! filters.empty())
            filters[0].setFirstOrderHighPass (freq);
        if (filters.size() > 1)
            filters[1].setHighPass (freq, 1.0f);
        for (std::size_t i = 2; i < filters.size(); ++i)
            filters[i].setBypass();
    }

    void setSecondOrderHighPass (float freq, float q = 0.7071f) noexcept
    {
        if (! filters.empty())
            filters[0].setHighPass (freq, q);
        for (std::size_t i = 1; i < filters.size(); ++i)
            filters[i].setBypass();
    }

    void setSecondOrderLowPass (float freq, float q = 0.7071f) noexcept
    {
        if (! filters.empty())
            filters[0].setLowPass (freq, q);
        for (std::size_t i = 1; i < filters.size(); ++i)
            filters[i].setBypass();
    }

private:
    std::vector<Biquad> filters;
};

/** Zero-stuffing 2x/4x oversampler with Butterworth interpolation filters. */
class Oversampler
{
public:
    Oversampler (int factor, float sampleRate)
        : factorValue (factor)
        , bufferL (static_cast<std::size_t> (factor), 0.0f)
        , bufferR (static_cast<std::size_t> (factor), 0.0f)
        , upL (sampleRate * factor, 2)
        , upR (sampleRate * factor, 2)
        , downL (sampleRate * factor, 2)
        , downR (sampleRate * factor, 2)
    {
        const float cutoff = sampleRate * 0.45f;
        upL.setButterworthLowPass (cutoff);
        upR.setButterworthLowPass (cutoff);
        downL.setButterworthLowPass (cutoff);
        downR.setButterworthLowPass (cutoff);
    }

    int factor() const noexcept { return factorValue; }

    void upsample (float inL, float inR) noexcept
    {
        std::fill (bufferL.begin(), bufferL.end(), 0.0f);
        std::fill (bufferR.begin(), bufferR.end(), 0.0f);
        bufferL[0] = inL * factorValue;
        bufferR[0] = inR * factorValue;
        for (int i = 0; i < factorValue; ++i)
        {
            bufferL[static_cast<std::size_t> (i)] = upL.process (bufferL[static_cast<std::size_t> (i)]);
            bufferR[static_cast<std::size_t> (i)] = upR.process (bufferR[static_cast<std::size_t> (i)]);
        }
    }

    void downsample (float* out) noexcept
    {
        float lastL = 0.0f, lastR = 0.0f;
        for (int i = 0; i < factorValue; ++i)
        {
            lastL = downL.process (bufferL[static_cast<std::size_t> (i)]);
            lastR = downR.process (bufferR[static_cast<std::size_t> (i)]);
        }
        out[0] = lastL;
        out[1] = lastR;
    }

    void reset() noexcept
    {
        upL.reset();
        upR.reset();
        downL.reset();
        downR.reset();
        std::fill (bufferL.begin(), bufferL.end(), 0.0f);
        std::fill (bufferR.begin(), bufferR.end(), 0.0f);
    }

    std::vector<float> bufferL, bufferR;

private:
    int factorValue;
    BiquadCascade upL, upR, downL, downR;
};

/** First-order smoothing coefficient for an attack/release time in ms. */
inline float dynCoeff (float ms, float sampleRate) noexcept
{
    return static_cast<float> (std::exp (-1.0 / ((static_cast<double> (std::max (ms, 0.005f)) * sampleRate) / 1000.0)));
}

/** Rectified peak detector with hold, the sidechain of every compressor. */
class PeakEnvelope
{
public:
    explicit PeakEnvelope (float sampleRate, float holdMs = 15.0f) noexcept
        : decay (dynCoeff (holdMs, sampleRate))
        , value (0.0f)
    {
    }

    float update (float x) noexcept
    {
        const float rectified = std::fabs (x);
        value = rectified > value ? rectified : value * decay;
        return value;
    }

    void reset() noexcept { value = 0.0f; }

private:
    float decay, value;
};

inline float smoothingStep (float coeff) noexcept
{
    const float step = 1.0f - coeff;
    return std::min (std::max (step, 0.0f), 1.0f);
}

inline float computeGainReductionDb (float levelDb, float thresholdDb, float ratio, float kneeDb) noexcept
{
    const float delta = levelDb - thresholdDb;
    const float half = kneeDb * 0.5f;
    const float slope = 1.0f - 1.0f / std::max (ratio, 1.0f);
    if (delta <= -half)
        return 0.0f;
    if (delta >= half)
        return slope * delta;
    const float t = (delta + half) / std::max (kneeDb, 0.0001f);
    return slope * (t * t * half);
}

class PeakMeter
{
public:
    float peak = 0.0f;

    void update (float l, float r) noexcept { peak = std::max (std::fabs (l), std::fabs (r)); }

    void reset() noexcept { peak = 0.0f; }
};

